import{_ as t,o as n,c as i,ag as o}from"./chunks/framework.8tqBsFWt.js";const c=JSON.parse('{"title":"Command by Intent","description":"","frontmatter":{"title":"Command by Intent","order":6},"headers":[],"relativePath":"about/chapters/06-command-by-intent.md","filePath":"about/chapters/06-command-by-intent.md"}'),a={name:"about/chapters/06-command-by-intent.md"};function l(r,e,s,d,m,u){return n(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="_06-command-by-intent" tabindex="-1">06.<br>Command by Intent <a class="header-anchor" href="#_06-command-by-intent" aria-label="Permalink to &quot;06.&lt;br&gt;Command by Intent&quot;">​</a></h3><h4 id="golden-rules-to-live-by" tabindex="-1">Golden Rules to Live By <a class="header-anchor" href="#golden-rules-to-live-by" aria-label="Permalink to &quot;Golden Rules to Live By&quot;">​</a></h4><blockquote><p>Command By Intent is a clear, concise statement of an operation&#39;s purpose and desired end state, enabling subordinates to exercise initiative and act independently to achieve goals, even if the original plan fails</p></blockquote><p>Life is made so much simpler by using this military doctrine (from the book <em>Extreme Ownership</em>) in agency operations, and almost no-one uses it because it requires trust in the people you hired. Despite the exhaustive, hire-wire job descriptions you send it out into the world, trust is rare in agencies, mostly because &#39;failure&#39; is forbidden. By defining golden rules and empowering your people to improvise, you liberate both parties. There will be mistakes. You will need to have adult conversations, give feedback, and criticize (each other). But the net result is true delegation that:</p><ol><li>Helps you face reality</li><li>Separates what you, as an owner, <em>do</em> and <em>own</em></li><li>Defines your operating values</li><li>Enables the Talent Siphon</li></ol><p>Put differently, you want a team that doesn&#39;t sit waiting to be told what to do. You want a team that learns and improves by learning <em>how to think</em>.</p><p>There are no commandments set in stone, but there are personal golden rules you demand of your people. Examples might look like:</p><ul><li>Projects end on time</li><li>No free work as concessions</li><li>No work happens out-of-hours unless in extreme need</li></ul><p>Another agencies&#39; golden rules might differ considerably:</p><ul><li>Clients get a reply inside 10 minutes in working hours</li><li>Always present to clients in person</li><li>Always prefer quality over deadlines. If we can make it better, but deliver late, we will</li></ul><p>This level of trust enables personal and professional development, creating a high-functioning team, faster and more effectively than hiring &#39;the best people&#39; you can find.</p>',11)])])}const h=t(a,[["render",l]]);export{c as __pageData,h as default};
